async function readCloud(){return await api('/rest/v1/alliance_members?select=name,power,t1,type&order=created_at.asc')}
function signedCompact(n){const x=Number(n)||0;return (x>0?'+':x<0?'−':'')+compactTHP(Math.abs(x))}
function growthClass(n){return Number(n)>0?'up':Number(n)<0?'down':'flat'}
async function loadRosterGrowth(){
 const powerEl=document.getElementById('dashboardPowerChange'),memberEl=document.getElementById('dashboardMemberChange'),trend=document.getElementById('dashboardGrowthTrend');
 if(!trend)return;
 try{
  const data=await api('/rest/v1/roster_growth_history?select=recorded_at,source_modified_at,member_count,total_thp&order=recorded_at.asc&limit=90');
  if(!data?.length)return;
  const first=data[0],last=data[data.length-1],prev=data.length>1?data[data.length-2]:null;
  const powerDelta=prev?Number(last.total_thp)-Number(prev.total_thp):0,memberDelta=prev?last.member_count-prev.member_count:0;
  const totalPowerDelta=Number(last.total_thp)-Number(first.total_thp),totalMemberDelta=last.member_count-first.member_count;
  if(powerEl){powerEl.className='metric-change '+growthClass(powerDelta);powerEl.textContent=prev?signedCompact(powerDelta)+' vs previous sync':'Baseline captured'}
  if(memberEl){memberEl.className='metric-change '+growthClass(memberDelta);memberEl.textContent=prev?(memberDelta>0?'+':'')+memberDelta+' vs previous sync':'Baseline captured'}
  const gp=document.getElementById('growthPowerDelta'),gm=document.getElementById('growthMemberDelta'),gc=document.getElementById('growthSnapshotCount'),period=document.getElementById('growthPeriod');
  if(gp){gp.className=growthClass(totalPowerDelta);gp.textContent=data.length>1?signedCompact(totalPowerDelta):'—'}
  if(gm){gm.className=growthClass(totalMemberDelta);gm.textContent=data.length>1?(totalMemberDelta>0?'+':'')+totalMemberDelta:'—'}
  if(gc)gc.textContent=data.length;
  if(period)period.textContent=data.length>1?new Date(first.recorded_at).toLocaleDateString(undefined,{month:'short',day:'numeric'})+' → '+new Date(last.recorded_at).toLocaleDateString(undefined,{month:'short',day:'numeric'}):'Baseline '+new Date(last.recorded_at).toLocaleDateString(undefined,{month:'short',day:'numeric'});
  if(data.length<2){trend.innerHTML='<div class="train-empty">Baseline captured at '+compactTHP(Number(last.total_thp))+' THP and '+last.member_count+' members. Growth will appear after the next changed Drive roster sync.</div>';return}
  const vals=data.map(x=>Number(x.total_thp)),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,w=800,h=150,pad=14;
  const pts=data.map((x,i)=>{const px=pad+(i/(data.length-1))*(w-pad*2),py=h-pad-((Number(x.total_thp)-min)/span)*(h-pad*2);return px.toFixed(1)+','+py.toFixed(1)}).join(' ');
  trend.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Total Power growth trend"><polyline points="'+pts+'" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="growth-axis"><span>'+new Date(first.recorded_at).toLocaleDateString()+' · '+compactTHP(Number(first.total_thp))+'</span><span>'+new Date(last.recorded_at).toLocaleDateString()+' · '+compactTHP(Number(last.total_thp))+'</span></div>';
 }catch(e){console.warn('Roster growth load failed',e);trend.innerHTML='<div class="train-empty">Growth history is temporarily unavailable.</div>'}
}
async function loadRosterSyncStatus(){
 const root=document.getElementById('rosterSyncStatus'),pill=document.getElementById('rosterSyncPill'),state=document.getElementById('rosterSyncState'),rows=document.getElementById('rosterSyncRows'),time=document.getElementById('rosterSyncTime'),source=document.getElementById('rosterSyncSource'),error=document.getElementById('rosterSyncError');
 if(!root)return;
 try{
   const data=await api('/rest/v1/roster_sync_status?source_key=eq.alliance_members_drive&select=source_name,last_synced_at,row_count,status,error_message&limit=1');
   const x=data?.[0];
   if(!x){pill.textContent='No sync yet';state.textContent='Waiting';rows.textContent='—';time.textContent='—';root.classList.remove('sync-ok','sync-error');return}
   const ok=x.status==='ok';
   root.classList.toggle('sync-ok',ok);root.classList.toggle('sync-error',!ok);
   pill.textContent=ok?'Synced':'Sync error';state.textContent=ok?'OK':'Error';rows.textContent=Number.isFinite(Number(x.row_count))?Number(x.row_count).toLocaleString():'—';
   time.textContent=x.last_synced_at?new Date(x.last_synced_at).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'—';
   source.textContent=x.source_name||'Alliance members Data / alliance_members.xlsm';
   if(error){error.hidden=!x.error_message;error.textContent=x.error_message||''}
 }catch(e){
   root.classList.remove('sync-ok');root.classList.add('sync-error');pill.textContent='Unavailable';state.textContent='Could not read status';if(error){error.hidden=false;error.textContent=e.message}
 }
}
