async function generateRole(role,week,startNumber=null){const existing=trainHistory.filter(x=>x.week_start===week&&x.role===role);if(existing.length)return;const q=eligibleQueue(role);if(!q.length)throw Error('No eligible '+role+' members are in the alliance roster.');let st={...(trainState[role]||{next_index:0,cycle:1})},rows=[];if(startNumber!==null){if(!Number.isInteger(startNumber)||startNumber<1||startNumber>q.length)throw Error('Start # for '+role+' must be between 1 and '+q.length+'.');st.next_index=startNumber-1;}for(let day=0;day<7;day++){if(st.next_index>=q.length){st.next_index=0;st.cycle++}rows.push({week_start:week,day_index:day,role,member_name:q[st.next_index],cycle:st.cycle});st.next_index++}await api('/rest/v1/train_rotation_history',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(rows)});await api('/rest/v1/train_rotation_state?role=eq.'+role,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({next_index:st.next_index,cycle:st.cycle,updated_at:new Date().toISOString()})})}
async function undoTrainWeek(){if(!cloudReady)return alert('Connect to the shared cloud first.');const week=comingWeekStart(),rows=trainHistory.filter(x=>x.week_start===week);if(!rows.length)return alert('There is no coming Train week to undo.');if(!confirm('Undo the coming week? This removes all 7 Conductor and 7 VIP assignments from history so you can generate it again.'))return;try{for(const role of ['conductor','vip']){const roleRows=rows.filter(x=>x.role===role).sort((a,b)=>a.day_index-b.day_index),q=eligibleQueue(role);if(roleRows.length){const first=roleRows[0],idx=q.findIndex(n=>n.toLocaleLowerCase()===first.member_name.toLocaleLowerCase());if(idx>=0){await api('/rest/v1/train_rotation_state?role=eq.'+role,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({next_index:idx,cycle:first.cycle,updated_at:new Date().toISOString()})})}}}await api('/rest/v1/train_rotation_history?week_start=eq.'+week,{method:'DELETE',headers:{Prefer:'return=minimal'}});document.getElementById('trainStartNumber').value='';await loadTrainData()}catch(e){alert('Could not undo Train week: '+e.message);await loadTrainData()}}
async function generateTrainWeek(){if(!cloudReady)return alert('Connect to the shared cloud first.');const week=comingWeekStart();if(trainHistory.some(x=>x.week_start===week))return alert('The coming week has already been generated.');const raw=document.getElementById('trainStartNumber').value.trim();const chosen=raw===''?null:Number(raw);try{await generateRole('conductor',week,chosen);await generateRole('vip',week,chosen);await loadTrainData()}catch(e){alert('Could not generate train week: '+e.message);await loadTrainData()}}
