let previousDailyEmail=null;
function generateDailyEmail(){const box=document.getElementById('dailyEmailText'),btn=document.getElementById('copyDailyEmailBtn'),undo=document.getElementById('undoDailyEmailBtn'),status=document.getElementById('dailyEmailStatus');if(!box)return;previousDailyEmail=box.value;box.value=dailyAllianceEmail();if(btn)btn.disabled=false;if(undo)undo.disabled=false;if(status)status.textContent='Generated from today’s live schedule. Undo is available.'}
function undoDailyEmail(){const box=document.getElementById('dailyEmailText'),undo=document.getElementById('undoDailyEmailBtn'),copy=document.getElementById('copyDailyEmailBtn'),status=document.getElementById('dailyEmailStatus');if(!box||previousDailyEmail===null)return;box.value=previousDailyEmail;previousDailyEmail=null;if(copy)copy.disabled=!box.value;if(undo)undo.disabled=true;if(status)status.textContent='Generation undone. Previous email restored.'}
async function copyDailyEmail(){const box=document.getElementById('dailyEmailText'),status=document.getElementById('dailyEmailStatus');if(!box?.value)return;try{await navigator.clipboard.writeText(box.value)}catch{box.focus();box.select();document.execCommand('copy')}if(status)status.textContent='Copied to clipboard.';setTimeout(()=>{if(status)status.textContent=''},2500)}
function renderShinyCalendar(){const root=document.getElementById('shinyCalendar');if(!root)return;const names=['July','August','September','October','November','December'],dow=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];root.innerHTML=names.map((name,mi)=>{const month=mi+6,first=new Date(2026,month,1),days=new Date(2026,month+1,0).getDate(),cells=[];dow.forEach(d=>cells.push('<span class="dow">'+d+'</span>'));for(let i=0;i<first.getDay();i++)cells.push('<span class="blank"></span>');for(let day=1;day<=days;day++){const d=new Date(2026,month,day),serial=Math.floor((d-new Date(2026,6,1))/86400000),cycle=((serial%3)+3)%3,group=cycle===0?'A':cycle===1?'B':'C',cls=cycle===0?'shiny-a':cycle===1?'shiny-b':'shiny-c';cells.push('<span class="day '+cls+'" data-shiny-date="'+d.getFullYear()+'-'+String(month+1).padStart(2,'0')+'-'+String(day).padStart(2,'0')+'" data-shiny-group="'+group+'" title="Group '+group+' · Cycle '+cycle+'">'+day+'</span>')}return '<div class="shiny-month"><h4>'+name+' 2026</h4><div class="shiny-grid">'+cells.join('')+'</div></div>'}).join('')}


const ROTATION_ANCHOR=new Date(2026,8,28,12);let rotationBlock=Math.max(0,Number(localStorage.getItem('unbeerable_rotation_block')||0));
function rotationEventsForDate(d){const serial=Math.round((new Date(d.getFullYear(),d.getMonth(),d.getDate(),12)-ROTATION_ANCHOR)/86400000),events=[];if((((serial-2)%3)+3)%3===0)events.push('🧟 Zombie Siege · 20h CET / 16h ST');if(((serial-1)%2+2)%2===0)events.push('🪖 Alliance Exercise · 21h CET / 17h ST');if(d.getDay()===4)events.push('🏜️ Canyon Storm · 16h CET / 12h ST');if(d.getDay()===5)events.push('🌪️ Desert Storm · Team A 13h CET / 9h ST · Team B 22h CET / 16h ST');return events.length?events:['🆓 Free time']}
function blockStart(block=rotationBlock){const d=new Date(ROTATION_ANCHOR);d.setDate(d.getDate()+block*28);return d}
function renderRotationCalendar(){const body=document.getElementById('rotationCalendarBody');if(!body)return;const start=blockStart(),days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],counts={marshal:0,zombie:0,canyon:0,desert:0,free:0};body.innerHTML=days.map((name,di)=>'<tr><th>'+name+'</th>'+[0,1,2,3].map(w=>{const d=new Date(start);d.setDate(d.getDate()+w*7+di);const ev=rotationEventsForDate(d);ev.forEach(e=>{if(e.includes('Alliance Exercise'))counts.marshal++;else if(e.includes('Zombie'))counts.zombie++;else if(e.includes('Canyon'))counts.canyon++;else if(e.includes('Desert'))counts.desert++;else if(e.includes('Free'))counts.free++});return '<td>'+ev.join('<br>')+'</td>'}).join('')+'</tr>').join('');document.getElementById('rotationTotals').innerHTML='<div><strong>'+counts.marshal+'</strong><span>🪖 Marshal</span></div><div><strong>'+counts.zombie+'</strong><span>🧟 Zombie Siege</span></div><div><strong>'+counts.canyon+'</strong><span>🏜️ Canyon Storm</span></div><div><strong>'+counts.desert+'</strong><span>🌪️ Desert Storm</span></div><div><strong>'+counts.free+'</strong><span>🆓 Free days</span></div>';const finish=new Date(start);finish.setDate(finish.getDate()+27);document.getElementById('rotationBlockLabel').textContent='Block '+(rotationBlock+1)+' · 4 weeks';const undo=document.getElementById('undoRotationBtn');if(undo)undo.disabled=rotationBlock<=0;document.getElementById('rotationRange').textContent=start.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})+' – '+finish.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
function todayRotation(){const now=allianceNow(),today=new Date(now),days=Math.floor((today-ROTATION_ANCHOR)/86400000),week=((Math.floor(days/7)%4)+4)%4+1;return{now,week,events:rotationEventsForDate(today)}}
function renderDashboardToday(){const date=document.getElementById('dashboardTodayDate'),week=document.getElementById('dashboardRotationWeek'),events=document.getElementById('dashboardTodayEvents'),weekEl=document.getElementById('dashboardWeekEvents');if(!date||!week||!events)return;const x=todayRotation(),now=x.now,today=new Date(now.getFullYear(),now.getMonth(),now.getDate(),12),dow=today.getDay()||7,monday=new Date(today);monday.setDate(today.getDate()-dow+1);date.textContent=now.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});week.textContent='Week '+x.week+' of 4';events.innerHTML=x.events.map(e=>'<div class="today-event">'+e+'</div>').join('');if(weekEl)weekEl.innerHTML=Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);const ev=rotationEventsForDate(d),isToday=d.toDateString()===today.toDateString();return '<div class="dashboard-week-day '+(isToday?'active':'')+'"><div class="dashboard-week-head"><strong>'+d.toLocaleDateString(undefined,{weekday:'short'})+'</strong><span>'+d.toLocaleDateString(undefined,{month:'short',day:'numeric'})+'</span></div><div class="dashboard-week-list">'+ev.map(e=>'<span>'+e+'</span>').join('')+'</div></div>'}).join('')}

function nextRotationBlock(){rotationBlock++;localStorage.setItem('unbeerable_rotation_block',rotationBlock);renderRotationCalendar()}
function undoRotationBlock(){if(rotationBlock<=0)return;rotationBlock--;localStorage.setItem('unbeerable_rotation_block',rotationBlock);renderRotationCalendar()}
function renderReminders(){const day=allianceNow().getDay(),names=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],desert=[1,2,3].includes(day),canyon=[6,0,1,2].includes(day),d=document.getElementById('desertReminder'),c=document.getElementById('canyonReminder'),label=document.getElementById('reminderDay');if(label)label.textContent=names[day];if(d)d.classList.toggle('active',desert);if(c)c.classList.toggle('active',canyon);const saved=localStorage.getItem('unbeerable_vs_strategy')||'',status=document.getElementById('vsStrategyStatus');document.querySelectorAll('.vs-choice').forEach(b=>b.classList.toggle('active',b.dataset.vsStrategy===saved));if(status)status.textContent=saved==='push'?'Selected: Push in VS':saved==='save'?'Selected: Save in VS':'No VS strategy selected.'}
renderVersus();renderMembers();renderShinyCalendar();renderReminders();renderRotationCalendar();renderDashboardToday();setInterval(renderDashboardToday,60000);initCloud();if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));